export type Origin = (typeof ORIGINS)[number];

// ─────────────────────────── runtime tests ───────────────────────────────

test('parseUser returns the parsed object', () => {
  eq(parseUser('{"id":1,"name":"Ada"}'), { id: 1, name: 'Ada' });
